SourceCode.Declaration:
/// <summary>
/// Central store Constract
/// </summary>
[DataContractAttribute, SysOperationContractProcessing(classStr(NDXCSDUIBuilder))]
public final class NDXCSDContract implements SysOperationInitializable
{
    boolean csdAll;
    Common common;
    NDXCentralStoreId csId;

    NDXCSDController controller;
    Dialog dialog;

    date validFrom;

    boolean allVisible;

}

Method.Source:
[DataMemberAttribute("csdAll"), SysOperationLabelAttribute("All"), SysOperationHelpText("@NDX:NDXCSDAll_Help"),  SysOperationDisplayOrder('3')]
public NoYes parmCSDAll(NoYes _csdAll= csdAll)
{
    csdAll = _csdAll;
    return csdAll;
}

[DataMemberAttribute("Common")]
public Common parmCommon(Common _common = common)
{
    common = _common;

    this.parmCSId();
    this.parmValidFrom();

    return common;
}

[DataMemberAttribute("ValidFrom"), SysOperationLabelAttribute("@NDX:ValidFrom"), SysOperationDisplayOrder('2')]
public date parmValidFrom(date _validFrom = validFrom)
{
    validFrom = _validFrom;

    if(common is NDX_CentralStoreDistributionTable)
    {
        NDX_CentralStoreDistributionTable lNDX_CentralStoreDistributionTable = common;
        validFrom = lNDX_CentralStoreDistributionTable.ValidFrom;
    }

    return validFrom;
}

[DataMemberAttribute("CentralStoreId"), SysOperationLabelAttribute("@NDX:NDXCSDId"), SysOperationDisplayOrder('1')]
public NDXCentralStoreId parmCSId(NDXCentralStoreId _csId = csId)
{
    csId = _csId;

    //priority is NDX_CentralStore storeid
    if(common is NDX_CentralStore)
    {
        NDX_CentralStore lNDX_CentralStore = common;
        csId = lNDX_CentralStore.CentralStoreId;
    }

    if(common is NDX_CentralStoreDistributionTable)
    {
        NDX_CentralStoreDistributionTable lNDX_CentralStoreDistributionTable = common;
        csId = lNDX_CentralStoreDistributionTable.CentralStoreId;
    }

    return csId;
}

public boolean parmAllVisible(boolean _allVisible = allVisible )
{
    allVisible = _allVisible;
    return allVisible;
}
